package com.kostin.app;
import android.app.Activity;import android.os.Bundle;import android.os.Handler;import android.graphics.BitmapFactory;import android.graphics.Color;import android.view.ViewGroup;import android.webkit.*;import android.widget.*;import android.content.Intent;import android.net.Uri;import java.util.Base64;
public class MainActivity extends Activity { WebView webView; FrameLayout root;
 public void onCreate(Bundle b){super.onCreate(b);root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(6,43,87));ImageView s=new ImageView(this);s.setScaleType(ImageView.ScaleType.CENTER_CROP);try{s.setImageBitmap(BitmapFactory.decodeByteArray(Base64.getDecoder().decode(LogoData.BASE64),0,Base64.getDecoder().decode(LogoData.BASE64).length));}catch(Exception ignored){}root.addView(s,new FrameLayout.LayoutParams(-1,-1));setContentView(root);new Handler().postDelayed(()->open(s),900);}
 void open(ImageView s){webView=new WebView(this);webView.getSettings().setJavaScriptEnabled(true);webView.getSettings().setDomStorageEnabled(true);webView.getSettings().setDatabaseEnabled(true);webView.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){if(u.startsWith("https://kost-in-three.vercel.app/")||u.startsWith("https://kost-in-tau.vercel.app/")){v.loadUrl(u);return true;}try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(u)));}catch(Exception ignored){}return true;}});webView.setWebChromeClient(new WebChromeClient());root.addView(webView,new FrameLayout.LayoutParams(-1,-1));webView.loadUrl("https://kost-in-three.vercel.app/");root.removeView(s);}
 @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}
